const {
  IMAGE_STATUS, IMAGE_ACTIONS, transitionFor, canTransition, nextImageStatus, canStartVideo
} = require('../../lib/imageReview');

const allowed = [
  ['not_requested', 'request', 'requested'],
  ['rejected', 'request', 'requested'],
  ['failed', 'request', 'requested'],
  ['requested', 'start', 'processing'],
  ['processing', 'complete', 'ready_for_review'],
  ['requested', 'fail', 'failed'],
  ['processing', 'fail', 'failed'],
  ['ready_for_review', 'approve', 'approved'],
  ['ready_for_review', 'reject', 'rejected']
];

describe('image review state machine', () => {
  it('exposes the seven statuses and six actions', () => {
    expect(IMAGE_STATUS).toEqual({
      NOT_REQUESTED: 'not_requested', REQUESTED: 'requested', PROCESSING: 'processing',
      READY_FOR_REVIEW: 'ready_for_review', APPROVED: 'approved', REJECTED: 'rejected', FAILED: 'failed'
    });
    expect(IMAGE_ACTIONS).toEqual({
      REQUEST: 'request', START: 'start', COMPLETE: 'complete', FAIL: 'fail', APPROVE: 'approve', REJECT: 'reject'
    });
    expect(Object.isFrozen(IMAGE_STATUS)).toBe(true);
    expect(Object.isFrozen(IMAGE_ACTIONS)).toBe(true);
  });

  it.each(allowed)('%s --%s--> %s', (from, action, to) => {
    expect(canTransition(from, action)).toBe(true);
    expect(nextImageStatus(from, action)).toBe(to);
  });

  it('rejects every other (status, action) pair, so a second approve/reject is impossible', () => {
    Object.values(IMAGE_STATUS).forEach((status) => {
      Object.values(IMAGE_ACTIONS).forEach((action) => {
        const ok = allowed.some(([f, a]) => f === status && a === action);
        expect(canTransition(status, action)).toBe(ok);
        if (!ok) {
          expect(() => nextImageStatus(status, action)).toThrow(`Cannot ${action} an image that is ${status}`);
        }
      });
    });
    expect(canTransition('approved', 'approve')).toBe(false);
    expect(canTransition('approved', 'reject')).toBe(false);
    expect(canTransition('rejected', 'approve')).toBe(false);
  });

  it('treats unknown actions and statuses as not allowed', () => {
    expect(canTransition('approved', 'bogus')).toBe(false);
    expect(canTransition('bogus', 'approve')).toBe(false);
    expect(() => nextImageStatus('bogus', 'approve')).toThrow('Cannot approve an image that is bogus');
    expect(() => nextImageStatus('ready_for_review', 'bogus')).toThrow('Cannot bogus an image that is ready_for_review');
  });

  it('transitionFor returns the table entry, including the job status', () => {
    expect(transitionFor('request')).toEqual({ from: ['not_requested', 'rejected', 'failed'], to: 'requested', jobStatus: 'queued' });
    expect(transitionFor('start')).toEqual({ from: ['requested'], to: 'processing', jobStatus: 'processing' });
    expect(transitionFor('complete')).toEqual({ from: ['processing'], to: 'ready_for_review', jobStatus: 'awaiting_review' });
    expect(transitionFor('fail')).toEqual({ from: ['requested', 'processing'], to: 'failed', jobStatus: 'failed' });
    expect(transitionFor('approve')).toEqual({ from: ['ready_for_review'], to: 'approved', jobStatus: 'queued' });
    expect(transitionFor('reject')).toEqual({ from: ['ready_for_review'], to: 'rejected', jobStatus: 'queued' });
    expect(transitionFor('bogus')).toBeNull();
  });

  it('transitionFor returns a copy that cannot change the machine', () => {
    const entry = transitionFor('request');
    entry.from.push('approved');
    entry.to = 'approved';
    expect(canTransition('approved', 'request')).toBe(false);
    expect(nextImageStatus('not_requested', 'request')).toBe('requested');
    expect(transitionFor('request').from).toEqual(['not_requested', 'rejected', 'failed']);
  });

  it('video can only start after the image is approved', () => {
    Object.values(IMAGE_STATUS).forEach((status) => {
      expect(canStartVideo({ imageStatus: status })).toBe(status === 'approved');
    });
    expect(canStartVideo(null)).toBe(false);
    expect(canStartVideo(undefined)).toBe(false);
    expect(canStartVideo({})).toBe(false);
  });
});

